import { useRef } from 'react'
import { motion, useInView, animate } from 'framer-motion'
import { useEffect, useState } from 'react'

function ArrowRightIcon(props) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" width="16" height="16" {...props}>
      <path d="M5 12h14M13 6l6 6-6 6" />
    </svg>
  )
}
function PlayIcon(props) {
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" width="14" height="14" {...props}>
      <path d="M8 5v14l11-7z" />
    </svg>
  )
}

const fadeUp = {
  hidden: { opacity: 0, y: 30 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.6 } },
}

const stagger = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.12 } },
}

function Counter({ value, suffix = '', duration = 1.8 }) {
  const ref = useRef(null)
  const inView = useInView(ref, { once: true, margin: '-50px' })
  const [display, setDisplay] = useState(0)

  useEffect(() => {
    if (!inView) return
    const controls = animate(0, value, {
      duration,
      ease: 'easeOut',
      onUpdate: (v) => setDisplay(Math.round(v)),
    })
    return () => controls.stop()
  }, [inView, value, duration])

  return (
    <span ref={ref}>
      {display}
      {suffix}
    </span>
  )
}

function GlobeVisual() {
  return (
    <div className="relative w-full aspect-square max-w-[560px] mx-auto select-none pointer-events-none">
      {/* Radial glow behind globe */}
      <div className="absolute inset-0 rounded-full bg-gradient-to-br from-blue-500/20 via-emerald-500/10 to-transparent blur-3xl" />

      <svg viewBox="0 0 400 400" className="relative w-full h-full">
        <defs>
          <radialGradient id="globeCore" cx="50%" cy="45%" r="60%">
            <stop offset="0%" stopColor="#1a3a6a" stopOpacity="0.9" />
            <stop offset="100%" stopColor="#020617" stopOpacity="0.2" />
          </radialGradient>
          <linearGradient id="ringGrad" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor="#3b82f6" />
            <stop offset="100%" stopColor="#34d399" />
          </linearGradient>
        </defs>

        <circle cx="200" cy="200" r="140" fill="url(#globeCore)" />

        {/* Latitude ellipses */}
        {[70, 100, 140].map((ry, i) => (
          <ellipse
            key={i}
            cx="200"
            cy="200"
            rx="140"
            ry={ry}
            fill="none"
            stroke="url(#ringGrad)"
            strokeOpacity="0.35"
            strokeWidth="1"
          />
        ))}

        {/* Rotating outer dashed rings */}
        <g style={{ transformOrigin: '200px 200px', animation: 'rotate 40s linear infinite' }}>
          <circle cx="200" cy="200" r="170" fill="none" stroke="#3b82f6" strokeOpacity="0.25" strokeWidth="1" strokeDasharray="4 8" />
        </g>
        <g style={{ transformOrigin: '200px 200px', animation: 'rotate 60s linear infinite reverse' }}>
          <circle cx="200" cy="200" r="190" fill="none" stroke="#34d399" strokeOpacity="0.2" strokeWidth="1" strokeDasharray="2 10" />
        </g>

        {/* Vertical meridian arcs */}
        {[0, 45, 90, 135].map((angle, i) => (
          <ellipse
            key={angle}
            cx="200"
            cy="200"
            rx="140"
            ry="140"
            fill="none"
            stroke="#60a5fa"
            strokeOpacity="0.18"
            strokeWidth="1"
            transform={`rotate(${angle} 200 200)`}
            style={{ transformOrigin: '200px 200px' }}
          />
        ))}

        {/* Glowing connection nodes */}
        {[
          [200, 60], [330, 140], [340, 260], [200, 340], [70, 260], [60, 140], [280, 90], [120, 320],
        ].map(([cx, cy], i) => (
          <circle key={i} cx={cx} cy={cy} r="4" fill="#34d399" style={{ animation: `pulse-glow ${3 + (i % 3)}s ease-in-out infinite`, animationDelay: `${i * 0.3}s` }} />
        ))}

        {/* Connection lines */}
        <g stroke="url(#ringGrad)" strokeOpacity="0.3" strokeWidth="1">
          <line x1="200" y1="60" x2="330" y2="140" />
          <line x1="330" y1="140" x2="340" y2="260" />
          <line x1="340" y1="260" x2="200" y2="340" />
          <line x1="200" y1="340" x2="70" y2="260" />
          <line x1="70" y1="260" x2="60" y2="140" />
          <line x1="60" y1="140" x2="200" y2="60" />
          <line x1="200" y1="60" x2="280" y2="90" />
          <line x1="120" y1="320" x2="70" y2="260" />
        </g>
      </svg>

      {/* Floating particles */}
      <div className="absolute top-6 right-10 w-2 h-2 rounded-full bg-blue-400 animate-float" />
      <div className="absolute bottom-16 left-4 w-1.5 h-1.5 rounded-full bg-emerald-400 animate-float-delayed" />
      <div className="absolute top-1/2 -right-2 w-2.5 h-2.5 rounded-full bg-cyan-400 animate-float" />
    </div>
  )
}

export default function Hero() {
