function Counter({ value, suffix, duration = 2 }) {
  const [displayValue, setDisplayValue] = useState(0)

  useEffect(() => {
    const controls = animate(0, value, {
      duration,
      ease: 'easeOut',
      onUpdate(latest) {
        setDisplayValue(Math.round(latest))
      },
    })

    return () => controls.stop()
  }, [duration, value])

  return (
    <span>
      {displayValue}
      {suffix}
    </span>
  )
}

